solution.alphametics.zig:
const std = @import("std");

pub const Solution = [26]i8; // A..Z, -1 for letters absent from the puzzle.
const Solver = struct {
    columns: [][26]i64,
    leading: [26]bool = @splat(false),
    present: [26]bool = @splat(false),
    digits: Solution = @splat(-1),
    used: [10]bool = @splat(false),
    fn search(self: *Solver, column: usize, carry: i64) bool {
        if (column == self.columns.len) {
            if (carry != 0) return false;
            for (self.present, 0..) |exists, c| if (exists and self.digits[c] < 0) {
                for (0..10) |digit| if (!self.used[digit] and (digit != 0 or !self.leading[c])) {
                    self.digits[c] = @intCast(digit);
                    self.used[digit] = true;
                    if (self.search(column, carry)) return true;
                    self.digits[c] = -1;
                    self.used[digit] = false;
                };
                return false;
            };
            return true;
        }
        var sum = carry;
        for (self.columns[column], 0..) |coefficient, c| {
            if (coefficient == 0) continue;
            if (self.digits[c] >= 0) {
                sum += coefficient * self.digits[c];
                continue;
            }
            for (0..10) |digit| if (!self.used[digit] and (digit != 0 or !self.leading[c])) {
                self.digits[c] = @intCast(digit);
                self.used[digit] = true;
                if (self.search(column, carry)) return true;
                self.digits[c] = -1;
                self.used[digit] = false;
            };
            return false;
        }
        return @mod(sum, 10) == 0 and self.search(column + 1, @divTrunc(sum, 10));
    }
};
pub fn solve(allocator: std.mem.Allocator, puzzle: []const u8) !?Solution {
    const columns = try allocator.alloc([26]i64, puzzle.len);
    defer allocator.free(columns);
    for (columns) |*column| column.* = @splat(0);
    var solver = Solver{ .columns = columns };
    var sign: i64 = 1;
    var max: usize = 0;
    var i: usize = 0;
    var equality = false;
    while (i < puzzle.len) {
        if (puzzle[i] == ' ' or puzzle[i] == '+' or puzzle[i] == '\t') {
            i += 1;
            continue;
        }
        if (puzzle[i] == '=') {
            if (equality) return error.InvalidPuzzle;
            equality = true;
            sign = -1;
            i += 1;
            if (i < puzzle.len and puzzle[i] == '=') i += 1;
            continue;
        }
        const begin = i;
        while (i < puzzle.len and std.ascii.isAlphabetic(puzzle[i])) : (i += 1) {}
        if (i == begin) return error.InvalidPuzzle;
        const word = puzzle[begin..i];
        max = @max(max, word.len);
        if (word.len > 1) solver.leading[std.ascii.toUpper(word[0]) - 'A'] = true;
        for (word, 0..) |raw, index| {
            const c = std.ascii.toUpper(raw) - 'A';
            solver.present[c] = true;
            columns[word.len - index - 1][c] += sign;
        }
    }
    if (!equality or max == 0) return error.InvalidPuzzle;
    var count: usize = 0;
    for (solver.present) |p| {
        if (p) count += 1;
    }
    if (count > 10) return null;
    solver.columns = columns[0..max];
    return if (solver.search(0, 0)) solver.digits else null;
}

tests.test_alphametics.zig:
const std = @import("std");
const t = std.testing;
const a = t.allocator;
const m = @import("alphametics.zig");
test "test_puzzle_with_three_letters" {
    const result = try m.solve(a, "I + BB == ILL");
    try t.expect(result != null);
    try t.expectEqual(@as(i8, 1), result.?[8]);
    try t.expectEqual(@as(i8, 9), result.?[1]);
    try t.expectEqual(@as(i8, 0), result.?[11]);
}
test "test_solution_must_have_unique_value_for_each_letter" {
    const result = try m.solve(a, "A == B");
    try t.expect(result == null);
}
test "test_leading_zero_solution_is_invalid" {
    const result = try m.solve(a, "ACA + DD == BD");
    try t.expect(result == null);
}
test "test_puzzle_with_two_digits_final_carry" {
    const result = try m.solve(a, "A + A + A + A + A + A + A + A + A + A + A + B == BCC");
    try t.expect(result != null);
    try t.expectEqual(@as(i8, 9), result.?[0]);
    try t.expectEqual(@as(i8, 1), result.?[1]);
    try t.expectEqual(@as(i8, 0), result.?[2]);
}
test "test_puzzle_with_four_letters" {
    const result = try m.solve(a, "AS + A == MOM");
    try t.expect(result != null);
    try t.expectEqual(@as(i8, 9), result.?[0]);
    try t.expectEqual(@as(i8, 2), result.?[18]);
    try t.expectEqual(@as(i8, 1), result.?[12]);
    try t.expectEqual(@as(i8, 0), result.?[14]);
}
test "test_puzzle_with_six_letters" {
    const result = try m.solve(a, "NO + NO + TOO == LATE");
    try t.expect(result != null);
    try t.expectEqual(@as(i8, 7), result.?[13]);
    try t.expectEqual(@as(i8, 4), result.?[14]);
    try t.expectEqual(@as(i8, 9), result.?[19]);
    try t.expectEqual(@as(i8, 1), result.?[11]);
    try t.expectEqual(@as(i8, 0), result.?[0]);
    try t.expectEqual(@as(i8, 2), result.?[4]);
}
test "test_puzzle_with_seven_letters" {
    const result = try m.solve(a, "HE + SEES + THE == LIGHT");
    try t.expect(result != null);
    try t.expectEqual(@as(i8, 4), result.?[4]);
    try t.expectEqual(@as(i8, 2), result.?[6]);
    try t.expectEqual(@as(i8, 5), result.?[7]);
    try t.expectEqual(@as(i8, 0), result.?[8]);
    try t.expectEqual(@as(i8, 1), result.?[11]);
    try t.expectEqual(@as(i8, 9), result.?[18]);
    try t.expectEqual(@as(i8, 7), result.?[19]);
}
test "test_puzzle_with_eight_letters" {
    const result = try m.solve(a, "SEND + MORE == MONEY");
    try t.expect(result != null);
    try t.expectEqual(@as(i8, 9), result.?[18]);
    try t.expectEqual(@as(i8, 5), result.?[4]);
    try t.expectEqual(@as(i8, 6), result.?[13]);
    try t.expectEqual(@as(i8, 7), result.?[3]);
    try t.expectEqual(@as(i8, 1), result.?[12]);
    try t.expectEqual(@as(i8, 0), result.?[14]);
    try t.expectEqual(@as(i8, 8), result.?[17]);
    try t.expectEqual(@as(i8, 2), result.?[24]);
}
test "test_puzzle_with_ten_letters" {
    const result = try m.solve(a, "AND + A + STRONG + OFFENSE + AS + A + GOOD == DEFENSE");
    try t.expect(result != null);
    try t.expectEqual(@as(i8, 5), result.?[0]);
    try t.expectEqual(@as(i8, 3), result.?[3]);
    try t.expectEqual(@as(i8, 4), result.?[4]);
    try t.expectEqual(@as(i8, 7), result.?[5]);
    try t.expectEqual(@as(i8, 8), result.?[6]);
    try t.expectEqual(@as(i8, 0), result.?[13]);
    try t.expectEqual(@as(i8, 2), result.?[14]);
    try t.expectEqual(@as(i8, 1), result.?[17]);
    try t.expectEqual(@as(i8, 6), result.?[18]);
    try t.expectEqual(@as(i8, 9), result.?[19]);
}
